package kr.workbench;
import javax.swing.*;
public final class StructuredCompareTest {
 static int checks;static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);checks++;System.out.println("PASS "+name);}
 public static void main(String[] args)throws Exception{String json="{\"a\":9007199254740993,\"한글\":[1,2]}";String f=StructuredCompare.format(json);check(f.contains("\n")&&f.contains("9007199254740993"),"JSON formatted without numeric conversion");check(StructuredCompare.format("<a><b>값</b></a>").contains("\n"),"XML formatted");String unsafe="<!DOCTYPE a SYSTEM 'file:///etc/passwd'><a/>";check(StructuredCompare.format(unsafe).equals(unsafe),"external XML blocked");check(StructuredCompare.compare(json,f,true).changes().isEmpty(),"format differences normalized");var insertion=StructuredCompare.compare("a\nc\nd","a\nb\nc\nd",false);check(insertion.changes().size()==1,"insert aligns later lines");check(insertion.left().split("\n")[2].equals("c")&&insertion.right().split("\n")[2].equals("c"),"matched lines remain aligned");check(StructuredCompare.compare("a\nb\nc","a\nc",false).changes().size()==1,"deletion one region");check(StructuredCompare.compare("x\na\ny","z\na\nw",false).changes().size()==2,"separated changes");check(StructuredCompare.compare("x".repeat(70000),"x",false).limited(),"large input bounded");check(StructuredCompare.format("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n\r\n{\"a\":1}").contains("\n  \"a\""),"HTTP body formatted");SwingUtilities.invokeAndWait(()->{var p=new StructuredComparePanel();p.leftInput.setText(json);p.rightInput.setText("{\"a\":2,\"한글\":[1,2]}");ComparisonTestSupport.compareAndWait(p);check(p.leftInput.getText().equals(json),"original paste preserved");check(p.leftView.getHighlighter().getHighlights().length>0&&p.rightView.getHighlighter().getHighlights().length>0,"both differences colored");p.next.doClick();check(p.current==0&&p.status.getText().contains("1 /"),"next navigates difference");p.previous.doClick();check(p.current==0,"navigation wraps");p.formatted.doClick(); ComparisonTestSupport.await(p);check(p.leftInput.getText().equals(json),"raw toggle retains original");p.rightInput.setText(json);ComparisonTestSupport.compareAndWait(p);check(!p.next.isEnabled()&&p.result.changes().isEmpty(),"identical disables navigation");});System.out.println("Structured compare: "+checks+" checks passed");}
}
